  "recovered_c": "uint64_t fn_19(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len <= out_cap) {\n    if (len != 0) {\n      for (size_t i = 0; i < len; i++) {\n        uint8_t bVar1 = (i & 7);\n        uint8_t bVar3 = (arg >> bVar1 * 8) & 0xFF;\n        out[i] = (bVar3 << bVar1 | bVar3 >> 8 - bVar1) ^ in[i] ^ (uint8_t)i;\n      }\n    }\n    return len;\n  }\n  return VERA_ERR;\n}"
